#include <stdint.h>
#include <stdio.h>
#include "stm32f7xx.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

uint8_t col_hits[4] = {0};

const unsigned char key_val[4][4] = {
		{'1', '2', '3', 'A'},
		{'4', '5', '6', 'B'},
		{'7', '8', '9', 'C'},
		{'*', '0', '#', 'D'},
};

/*
 * Pinout:
 * PI1  = D13 = C1
 * PI2  = D8  = C2
 * PI3  = D7  = C3
 * PI0  = D5  = C4
 * PB8  = D15 = R1
 * PB9  = D14 = R2
 * PB14 = D12 = R3
 * PB15 = D11 = R4
 * */
int main(void)
{
	// DRIVE STUFF!!
    // Init registers

	// Enable port I, then enable port B
	RCC->AHB1ENR |= (1UL << 8) | (1UL << 1);

    // Bit 14 enables SYSCFG clock (for routing GPIO to EXTI)
    RCC->APB2ENR |= (1UL << 14);

    // Initialize GPIO pins

    // PB8  = D15 = R1
    GPIOB->MODER &= ~(3UL << (8 * 2));
    GPIOB->MODER |= (1UL << (8 * 2));
    GPIOB->PUPDR &= ~(3UL << (8 * 2));

    // PB9  = D14 = R2
    GPIOB->MODER &= ~(3UL << (9 * 2));
    GPIOB->MODER |= (1UL << (9 * 2));
    GPIOB->PUPDR &= ~(3UL << (9 * 2));

    // PB14 = D12 = R3
    GPIOB->MODER &= ~(3UL << (14 * 2));
    GPIOB->MODER |= (1UL << (14 * 2));
    GPIOB->PUPDR &= ~(3UL << (14 * 2));

    // PB15 = D11 = R4
    GPIOB->MODER &= ~(3UL << (15 * 2));
    GPIOB->MODER |= (1UL << (15 * 2));
    GPIOB->PUPDR &= ~(3UL << (15 * 2));

    // Set all columns as digital inputs w/ pull up resistor
    // PI1  = D13 = C1
    GPIOI->MODER &= ~(3UL << (1 * 2));
    GPIOI->PUPDR &= ~(3UL << (1 * 2));
    GPIOI->PUPDR |=  (1UL << (1 * 2));

    // PI2  = D8  = C2
    GPIOI->MODER &= ~(3UL << (2 * 2));
    GPIOI->PUPDR &= ~(3UL << (2 * 2));
    GPIOI->PUPDR |=  (1UL << (2 * 2));

    // PI3  = D7  = C3
    GPIOI->MODER &= ~(3UL << (3 * 2));
    GPIOI->PUPDR &= ~(3UL << (3 * 2));
    GPIOI->PUPDR |=  (1UL << (3 * 2));

    // PI0  = D5  = C4
    GPIOI->MODER &= ~(3UL << (0 * 2));
    GPIOI->PUPDR &= ~(3UL << (0 * 2));
    GPIOI->PUPDR |=  (1UL << (0 * 2));

    // Drive all rows low
    GPIOB->BSRR = (1UL << (8 + 16));
    GPIOB->BSRR = (1UL << (9 + 16));
    GPIOB->BSRR = (1UL << (14 + 16));
    GPIOB->BSRR = (1UL << (15 + 16));

    // Configure EXTI0
    SYSCFG->EXTICR[0] &= ~(0xFUL << (0 * 4));
    SYSCFG->EXTICR[0] |=  (0x8UL << (0 * 4));

    EXTI->IMR  |= (1UL << 0);  // Unmask line 0
    EXTI->FTSR |= (1UL << 0);  // Enable fall register
    EXTI->RTSR &= ~(1UL << 0); // Disable rise register

    NVIC->ISER[0] |= (1UL << 6);         //Enable IRQ 6

    // Configure EXTI1
    SYSCFG->EXTICR[0] &= ~(0xFUL << (1 * 4));
    SYSCFG->EXTICR[0] |=  (0x8UL << (1 * 4));

    EXTI->IMR  |= (1UL << 1);  // Unmask line 1
    EXTI->FTSR |= (1UL << 1);  // Enable fall register
    EXTI->RTSR &= ~(1UL << 1); // Disable rise register

    NVIC->ISER[0] |= (1UL << 7);         //Enable IRQ 7

    // Configure EXTI2
    SYSCFG->EXTICR[0] &= ~(0xFUL << (2 * 4));
    SYSCFG->EXTICR[0] |=  (0x8UL << (2 * 4));

    EXTI->IMR  |= (1UL << 2);  // Unmask line 2
    EXTI->FTSR |= (1UL << 2);  // Enable fall register
    EXTI->RTSR &= ~(1UL << 2); // Disable rise register

    NVIC->ISER[0] |= (1UL << 8);         //Enable IRQ 8

    // Configure EXTI3
    SYSCFG->EXTICR[0] &= ~(0xFUL << (3 * 4));
    SYSCFG->EXTICR[0] |=  (0x8UL << (3 * 4));

    EXTI->IMR  |= (1UL << 3);  // Unmask line 3
    EXTI->FTSR |= (1UL << 3);  // Enable fall register
    EXTI->RTSR &= ~(1UL << 3); // Disable rise register

    NVIC->ISER[0] |= (1UL << 9);         //Enable IRQ 9

    while (1) {};
}

void EXTI0_IRQHandler(void) {
    if (EXTI->PR & (1UL << 0)) {

		col_hits[0]++;

		// Flip rows to inputs with pull-up resistors
		// PB8  = D15 = R1
		GPIOB->MODER &= ~(3UL << (8 * 2));
		GPIOB->PUPDR &= ~(3UL << (8 * 2));
		GPIOB->PUPDR |= (1UL << (8 * 2));

		// PB9  = D14 = R2
		GPIOB->MODER &= ~(3UL << (9 * 2));
		GPIOB->PUPDR &= ~(3UL << (9 * 2));
		GPIOB->PUPDR |= (1UL << (9 * 2));

		// PB14 = D12 = R3
		GPIOB->MODER &= ~(3UL << (14 * 2));
		GPIOB->PUPDR &= ~(3UL << (14 * 2));
		GPIOB->PUPDR |= (1UL << (14 * 2));

		// PB15 = D11 = R4
		GPIOB->MODER &= ~(3UL << (15 * 2));
		GPIOB->PUPDR &= ~(3UL << (15 * 2));
		GPIOB->PUPDR |= (1UL << (15 * 2));


		// Flip columns to outputs, and drive them all low
		// PI1  = D13 = C1
		GPIOI->MODER &= ~(3UL << (1 * 2));
		GPIOI->MODER |= (1UL << (1 * 2));
		GPIOI->PUPDR &= ~(3UL << (1 * 2));

		// PI2  = D8  = C2
		GPIOI->MODER &= ~(3UL << (2 * 2));
		GPIOI->MODER |= (1UL << (2 * 2));
		GPIOI->PUPDR &= ~(3UL << (2 * 2));

		// PI3  = D7  = C3
		GPIOI->MODER &= ~(3UL << (3 * 2));
		GPIOI->MODER |= (1UL << (3 * 2));
		GPIOI->PUPDR &= ~(3UL << (3 * 2));

		// PI0  = D5  = C4
		GPIOI->MODER &= ~(3UL << (0 * 2));
		GPIOI->MODER |= (1UL << (0 * 2));
		GPIOI->PUPDR &= ~(3UL << (0 * 2));

		// Drive all cols low
		GPIOI->BSRR = (1UL << (0 + 16));
		GPIOI->BSRR = (1UL << (1 + 16));
		GPIOI->BSRR = (1UL << (2 + 16));
		GPIOI->BSRR = (1UL << (3 + 16));

		unsigned int row, col = 0;

		for (unsigned int i = 0; i < 4; i++) {
			// Enable column i
			GPIOI->BSRR = (1UL << ((i + 1) % 4));

			// Check PB8  = D15 = R1
			if (GPIOB->IDR & 0x0100) {
				row = 1;
				col = i;
				break;
			}

			// Check PB9  = D14 = R2
			if (GPIOB->IDR & 0x0200) {
				row = 2;
				col = i;
				break;
			}

			// Check PB14 = D12 = R3
			if (GPIOB->IDR & 0x4000) {
				row = 3;
				col = i;
				break;
			}

			// Check PB15 = D11 = R4
			if (GPIOB->IDR & 0x8000) {
				row = 4;
				col = i;
				break;
			}

			// Disable column i
			GPIOI->BSRR = (1UL << (i + 16));
		}

		char result = key_val[row][col];

		EXTI->PR = (1UL << 0); // Clear EXTI pending flag
		NVIC->ICPR[0] = (1UL << 6);   // Clear NVIC Pending bit for IRQ6
    }
}

void EXTI1_IRQHandler(void) {
    if (EXTI->PR & (1UL << 1)) {

     col_hits[1]++;

	 EXTI->PR = (1UL << 1); // Clear EXTI pending flag
	 NVIC->ICPR[0] = (1UL << 7);   // Clear NVIC Pending bit for IRQ7
    }
}

void EXTI2_IRQHandler(void) {
    if (EXTI->PR & (1UL << 2)) {

     col_hits[2]++;

	 EXTI->PR = (1UL << 2); // Clear EXTI pending flag
	 NVIC->ICPR[0] = (1UL << 8);   // Clear NVIC Pending bit for IRQ8
    }
}

void EXTI3_IRQHandler(void) {
    if (EXTI->PR & (1UL <<3)) {
   	 col_hits[3]++;

	 EXTI->PR = (1UL << 3); // Clear EXTI pending flag
	 NVIC->ICPR[0] = (1UL << 9);   // Clear NVIC Pending bit for IRQ9
    }
}
